                fre[num] += 1

        rep = 0
        mis = 0

        # Find repeating and missing numbers
        for j in range(1, len(fre) - 1):
            if fre[j] == 0:
                mis = j
            elif fre[j] == 2:
                rep = j

        return [rep, mis]

class Solution:
    def maximumLength(self, s: str) -> int:
        n = len(s)
        result = -1
        i = n - 3
        d = {}
        count = 0
        j = i
        found = False

        # Check if all characters are the same
        if len(set(s)) == len(s):
            return -1

        while i >= 0:
            d = {}
            count = 0

            j = i
            while j < n:
                # Check if current character forms a special substring of length 1
                if len(set(s[count:count+1])) == 1:
                    if s[count] in d:
                        d[s[count]] += 1
                    else:
                        d[s[count]] = 1

                    if d[s[count]] == 3:
                        result = max(result, count + 1)
                        found = True

                    count += 1
                else:
                    count += 1

                j += 1

            i -= 1

        return result

class Solution:
    def maximumLength(self, s: str) -> int:
        ans = 0
        freq = [[] for _ in range(26)]
        i = 0

        while i < len(s):
            j = i
            while j < len(s) and s[j] == s[i]:
                j += 1
            freq[ord(s[j-1]) - ord('a')].append(j - i)
            i = j

        for x in freq:
            if not x:
                continue
            x.sort()
            n = len(x)
            if n == 1:
                ans = max(ans, x[0])
            elif n == 2:
                ans = max(ans, min(x[1] - 1, x[0]))
            else:
                ans = max(ans, x[n-1] - 2)
                ans = max(ans, min(x[n-1] - 1, x[n-2]))
                ans = max(ans, x[n-3])

        return ans if ans > 0 else -1
